  LOOP
    UPDATE clients SET
      company_name = r.comp_name,
      tax_regime = r.tax_reg,
      monthly_value = r.monthly::numeric,
      sci_code = r.sci,
      trade_name = CASE WHEN r.trade = '' THEN trade_name ELSE r.trade END,
      status = r.stat::client_status,
      business_classification = CASE WHEN (business_classification IS NULL OR business_classification = '') AND r.biz_class != '' THEN r.biz_class ELSE business_classification END
    WHERE REGEXP_REPLACE(document, '[^0-9]', '', 'g') = r.cnpj_digits;
  END LOOP;

