  LOOP
    IF NOT EXISTS (SELECT 1 FROM clients WHERE REGEXP_REPLACE(document, '[^0-9]', '', 'g') = r.cnpj_digits) THEN
      INSERT INTO clients (company_name, document, sci_code, monthly_value, tax_regime, business_classification, trade_name, status)
      VALUES (r.comp_name, 
        SUBSTRING(r.cnpj_digits FROM 1 FOR 2) || '.' || SUBSTRING(r.cnpj_digits FROM 3 FOR 3) || '.' || SUBSTRING(r.cnpj_digits FROM 6 FOR 3) || '/' || SUBSTRING(r.cnpj_digits FROM 9 FOR 4) || '-' || SUBSTRING(r.cnpj_digits FROM 13 FOR 2),
        r.sci, r.monthly::numeric, r.tax_reg, r.biz_class, r.trade, r.stat::client_status);
    END IF;
  END LOOP;
